let lastFocus = null, toastTimer;
function persist(name) { save(name,state[name]); }
function toast(message) { const el=$('#toast'); el.textContent=message; el.classList.add('visible'); clearTimeout(toastTimer); toastTimer=setTimeout(()=>el.classList.remove('visible'),3500); }
function button(text,action,kind='',data='') { return `<button class="btn ${kind}" data-action="${action}" ${data}>${text}</button>`; }
function badge(text,kind='') { return `<span class="badge ${kind}">${escapeHTML(text)}</span>`; }
function metric(label,value,foot,name,positive=false) { return `<div class="card metric"><div class="metric-top"><span>${label}</span><span class="metric-icon">${icon(name)}</span></div><strong>${value}</strong><small class="${positive?'positive':''}">${foot}</small></div>`; }
function metrics(items) { return `<div class="metrics">${items.map(item=>metric(...item)).join('')}</div>`; }
function head(title,subtitle,action='') { return `<div class="page-head"><div><div class="eyebrow">Your marketing workspace</div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div><div class="actions">${action}</div></div>`; }
function smart(title,text) { return `<div class="card smart"><div class="smart-icon">${icon('studio')}</div><span class="eyebrow">A little clarity goes a long way</span><h2>${title}</h2><p>${text}</p>${button(`${icon('studio')} Open Assistant`,'assistant','primary')}<p class="small-text">Local demo assistant · simulated responses</p></div>`; }
function search(value,label,id) { return `<div class="search">${icon('search')}<input id="${id}" type="search" aria-label="${label}" placeholder="${label}" value="${escapeHTML(value)}"></div>`; }
function options(values,selected) { return values.map(v=>`<option ${v===selected?'selected':''}>${escapeHTML(v)}</option>`).join(''); }
function empty(title,text='') { return `<div class="empty">${icon('assets')}<h3>${title}</h3><p>${text}</p></div>`; }
function shell() {
 document.documentElement.dataset.theme=state.theme;
 if(state.view==='login') { $('#app').innerHTML=loginView(); return; }
 const name=routes.find(r=>r[0]===state.view)?.[1] || 'Dashboard';
 $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-icon">j</span><span class="brand-text">Jobgen<small>Marketing OS</small></span></div><div class="workspace"><small>WORKSPACE</small>Jobgen.ai Marketing <span style="float:right">⌄</span></div><div class="nav-caption">WORKSPACE</div><nav class="nav" aria-label="Main navigation">${routes.map(([id,label])=>`<button data-view="${id}" class="${state.view===id?'active':''}" ${state.view===id?'aria-current="page"':''} title="${label}">${icon(id)}<span class="nav-label">${label}</span></button>`).join('')}</nav><div class="sidebar-footer"><div class="local-pill">Frontend demo · saved locally</div><button class="profile" data-view="login"><span class="avatar">JM</span><span>Jobgen Marketing<small>Workspace admin · Sign in</small></span>${icon('logout')}</button></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">Workspace <span style="margin:0 9px">/</span><b>${name}</b></div><div class="top-actions"><span class="status">✦ Your marketing, in one place</span><button class="icon-btn" data-action="theme" aria-label="Switch to ${state.theme==='light'?'dark':'light'} mode">${icon(state.theme==='light'?'moon':'sun')}</button><button class="icon-btn" data-view="login" aria-label="Open login screen">${icon('leads')}</button></div></header><div class="content" id="view">${views[state.view]()}</div></main></div>`;
}
function navigate(view) { if(!views[view] && view!=='login') return; closeModal(); state.view=view; shell(); window.scrollTo(0,0); }
