 return head('Workboard','Less scattered work. More meaningful progress.',button(icon('plus')+' New task','task-new','primary'))+metrics([['Total tasks',state.tasks.length,'Your team’s shared work','workboard'],['In progress',state.tasks.filter(t=>t.status==='in_progress').length,'Moving things forward','automations'],['In review',state.tasks.filter(t=>t.status==='review').length,'Ready for a second look','studio'],['Completed',state.tasks.filter(t=>t.status==='done').length,'Small wins add up','dashboard']])+`<div class="toolbar">${search(state.taskSearch,'Search tasks','task-search')}<select id="priority-filter" aria-label="Filter task priority" style="width:160px">${options(['All','High','Medium','Low'],state.taskPriority)}</select></div><div class="board-layout"><section class="card priority-panel"><h3>Priority Tasks</h3><p class="muted small-text">Keep the important work close.</p><div class="priority-list">${state.tasks.filter(t=>t.priority==='High'&&t.status!=='done').map(t=>`<div class="row"><div><div class="row-title">${escapeHTML(t.title)}</div><div class="row-meta">${escapeHTML(t.assignee)} · ${escapeHTML(t.due)}</div><div style="margin-top:9px">${button('Edit task','task-edit','small',`data-id="${t.id}"`)}</div></div></div>`).join('') || '<p class="muted small-text">No high-priority tasks.</p>'}</div></section><div class="board" aria-label="Task board">${statuses.map(([id,name])=>`<section class="column" data-status="${id}" aria-label="${name}"><div class="column-head">${name} ${badge(filtered.filter(t=>t.status===id).length)}</div>${filtered.filter(t=>t.status===id).map(taskCard).join('')}<p class="muted" style="font-size:9px;text-align:center">Drop a task here</p></section>`).join('')}</div></div><p class="muted small-text">Drag cards between columns, or use each card’s status selector on touch devices and with a keyboard.</p>`;
