function openModal(title,body,wide=false) { lastFocus=document.activeElement; $('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${escapeHTML(title)}" tabindex="-1"><div class="modal-head"><h2>${title}</h2><button class="icon-btn" data-action="modal-close" aria-label="Close dialog">${icon('close')}</button></div>${body}</section></div>`;document.body.style.overflow='hidden';$('.modal').focus(); }
function closeModal() { $('#modal-root').innerHTML=''; document.body.style.overflow='';lastFocus?.focus?.(); }
function formField(label,name,value='',type='text',required=true) { return `<div class="field"><label for="form-${name}">${label}</label><input id="form-${name}" name="${name}" type="${type}" value="${escapeHTML(value)}" ${required?'required':''} ${type==='number'?'min="0" max="100000000"':'maxlength="500"'}></div>`; }
function selectField(label,name,values,value) { return `<div class="field"><label for="form-${name}">${label}</label><select name="${name}" id="form-${name}">${options(values,value)}</select></div>`; }
