function taskDialog(id) { const t=state.tasks.find(t=>t.id===id);openModal(t?'Edit task':'Create a task',`<form id="task-form" data-id="${id||''}">${formField('Task title','title',t?.title)}<div class="field"><label for="form-description">Description</label><textarea id="form-description" name="description" maxlength="2000">${escapeHTML(t?.description)}</textarea></div><div class="form-grid">${selectField('Priority','priority',['High','Medium','Low'],t?.priority||'Medium')}<div class="field"><label for="form-status">Status</label><select id="form-status" name="status">${statuses.map(([id,n])=>`<option value="${id}" ${id===(t?.status||'backlog')?'selected':''}>${n}</option>`).join('')}</select></div>${formField('Assignee','assignee',t?.assignee||'You')}${formField('Due date','due',t?.due||today,'date')}</div>${formFooter('Save task')}</form>`); }
function eventDialog(id,date=today) { const e=state.events.find(e=>e.id===id);openModal(e?'Edit scheduled post':'Schedule a post',`<form id="event-form" data-id="${id||''}">${formField('Post title','title',e?.title)}${selectField('Platform','platform',['Instagram','Facebook','LinkedIn'],e?.platform||state.preferences.platform)}<div class="form-grid">${formField('Date','date',e?.date||date,'date')}${formField('Time','time',e?.time||'09:00','time')}</div><div class="field"><label for="form-caption">Caption / notes</label><textarea id="form-caption" name="caption" maxlength="5000">${escapeHTML(e?.caption)}</textarea></div><div class="notice">Saved to your local calendar. This does not publish a post.</div><div class="modal-foot">${e?button('Delete post','event-delete','danger',`data-id="${e.id}"`):''}${button('Cancel','modal-close')}<button class="btn primary" type="submit">Save schedule</button></div></form>`); }
