function assistantDialog() { openModal('Your creative thinking partner',`<div class="notice">Simulated assistant · local responses, no AI service or media analysis.</div><label for="assistant-question">What would you like to work on?</label><textarea id="assistant-question" placeholder="Ask for post ideas, campaign angles or a clearer plan…"></textarea><div class="assistant-chips">${['Give me 5 LinkedIn post ideas','Plan a hiring campaign','Improve my next caption'].map(t=>button(t,'assistant-chip','small',`data-question="${t}"`)).join('')}</div>${button(icon('studio')+' Ask assistant','assistant-ask','primary')}<div id="assistant-answer" aria-live="polite"></div>`,true); }
let assistantRequest=0;
function assistantAnswer(question) { if(!question.trim()){toast('Add a question first.');return;}const target=$('#assistant-answer');if(!target)return;const request=++assistantRequest;target.innerHTML='<div class="assistant-response">Thinking through a few ideas…</div>';setTimeout(()=>{if(request!==assistantRequest||!target.isConnected)return;const answer=/campaign/i.test(question)?'A simple hiring campaign plan:\n\n1. Lead with a human story: a team member’s next chapter.\n2. Share one concrete hiring challenge and a useful insight.\n3. Publish a product walkthrough focused on outcomes.\n4. Invite your audience to explore Jobgen.ai.\n5. Review saves, conversations and qualified leads after a week.':/caption/i.test(question)?'Make your caption feel clear and human:\n\nStart with one specific problem your audience recognizes. Keep the middle focused on a useful takeaway. End with a single action.\n\nExample: “The right opportunity can change everything. At Jobgen.ai, we help talent and teams find that next chapter. What does a better hiring experience look like to you?”':'Five LinkedIn ideas for Jobgen.ai:\n\n1. Three hiring habits worth leaving behind.\n2. A founder’s lesson about building people-first teams.\n3. A carousel: what candidates wish employers knew.\n4. A behind-the-scenes look at making hiring simpler.\n5. A question: what made your best career move possible?\n\nPick one story, one useful insight and one clear call to action.';target.innerHTML=`<div class="assistant-response">${escapeHTML(answer)}</div>`;},900); }
function generateContent(regenerate=false) {
 const s=state.studio;if(!s.file||s.loading)return;
 s.platform=$('#studio-platform')?.value||s.platform||state.preferences.platform;s.tone=$('#studio-tone')?.value||s.tone||state.preferences.tone;s.notes=$('#studio-notes')?.value??s.notes;
 if(regenerate)s.variant++;s.loading=true;refreshView();
 setTimeout(()=>{const intros={Professional:'Better hiring starts with a clearer connection.',Friendly:'Your next chapter could be closer than you think. ✨',Bold:'Great talent deserves more than another application.',Inspirational:'Every opportunity begins with someone believing in what’s possible.'};const hook=s.variant%2?'A fresh perspective can open the right doors.':'Let’s make the next opportunity count.';s.output={analysis:`${s.file.type.startsWith('video')?'Video':'Image'} selected for ${s.platform}. A ${s.tone.toLowerCase()} voice with a people-first hiring message. This is a mock creative direction; the file’s contents have not been analyzed.`,caption:`${intros[s.tone]}\n\nAt Jobgen.ai, we’re bringing people and possibilities together — helping teams find their next great hire and talent find a meaningful next step.${s.notes?'\n\n'+s.notes:''}\n\n${hook}${s.platform==='LinkedIn'?' What would a better hiring experience look like for your team?':''}`,hashtags:s.platform==='LinkedIn'?'#JobgenAI #FutureOfWork #TalentAcquisition #Hiring':'#JobgenAI #CareerGrowth #HiringMadeHuman #NewOpportunities #YourNextChapter',cta:'Explore your next opportunity at Jobgen.ai.'};s.loading=false;if(state.view==='studio')refreshView();toast('Your simulated content is ready.');},900);
}
function studioFile(file) { if(!file)return;if(!/^(image|video)\//.test(file.type)||file.size>100*1024*1024){toast('Choose an image or video under 100 MB.');return;}if(state.studio.url)URL.revokeObjectURL(state.studio.url);state.studio.file=file;state.studio.url=URL.createObjectURL(file);state.studio.output=null;refreshView(); }
let selectedFiles=[];
function uploadDialog(){selectedFiles=[];openModal('Upload assets',`<div class="notice">Up to 10 files per upload, 100 MB each. Images, videos, PDFs and documents stay on your device.</div><div class="dropzone" id="asset-drop">${icon('upload')}<h3>Build your creative collection</h3><p>Drop files here or browse your device.</p><input type="file" id="asset-files" multiple accept="image/*,video/*,.pdf,.doc,.docx,.txt,.csv,.xls,.xlsx,.ppt,.pptx,.odt,.rtf,.md" aria-label="Choose asset files"></div><div id="upload-list" class="upload-list"></div><div class="modal-foot">${button('Cancel','modal-close')}<button class="btn primary" data-action="asset-save" disabled>Upload assets</button></div>`);}
function chooseAssets(files){const valid=[...files].filter(f=>f.size<=100*1024*1024&&(/^(image|video)\//.test(f.type)||/\.(pdf|docx?|txt|csv|xlsx?|pptx?|odt|rtf|md)$/i.test(f.name)));if(valid.length!==files.length)toast('Unsupported or oversized files were skipped.');selectedFiles=[...selectedFiles,...valid].slice(0,10);if(valid.length>10)toast('Only the first 10 files were selected.');$('#upload-list').innerHTML=selectedFiles.map(f=>`<div class="row"><span>${escapeHTML(f.name)}</span><span class="muted">${formatSize(f.size)}</span></div>`).join('');const btn=$('[data-action="asset-save"]');btn.disabled=!selectedFiles.length;btn.textContent=`Upload ${selectedFiles.length} asset${selectedFiles.length===1?'':'s'}`;}
document.addEventListener('click',event=>{
 const navigation=event.target.closest('[data-view]');if(navigation){navigate(navigation.dataset.view);return;}
 const tab=event.target.closest('[data-asset-tab]');if(tab){state.assetTab=tab.dataset.assetTab;refreshView();return;}
 const target=event.target.closest('[data-action]');if(target){const action=target.dataset.action,id=target.dataset.id,p=target.dataset.provider;
 if(action.startsWith('go-')){navigate(action.slice(3));return;}
 const handlers={
 'planner-toggle-source':()=>{state.plannerSource=state.plannerSource==='embedded'?'live':'embedded';persist('plannerSource');refreshView();toast('Switched to '+(state.plannerSource==='embedded'?'Embedded App':'Live Server (Port 3000)'));},
 'planner-reload':()=>{const iframe=$('#planner-iframe');if(iframe){iframe.src=iframe.src;toast('Workflow Planner reloaded.');}},
 'planner-fullscreen':()=>{const c=$('#planner-container');if(c){if(!document.fullscreenElement){c.requestFullscreen?.().catch(()=>{});}else{document.exitFullscreen?.().catch(()=>{});}}},
 'theme':()=>{state.theme=state.theme==='light'?'dark':'light';persist('theme');try{localStorage.setItem('wp_theme',state.theme);}catch(e){}shell();},'modal-close':closeModal,
 'brief':()=>openModal('Your AI Daily Brief',`<div class="notice">Simulated brief · demo insights</div><p><b>Today’s focus:</b> move your highest-impact work from review to ready.</p><p>Finish the LinkedIn carousel, review this week’s creative direction and follow up with qualified leads. Your strongest content combines useful hiring insights with a human story.</p><p><b>One idea to try:</b> ask your audience which part of hiring they would simplify first.</p>${button('Open Workboard','go-workboard','primary')}`),
 'assistant':assistantDialog,'assistant-chip':()=>{$('#assistant-question').value=target.dataset.question;assistantAnswer(target.dataset.question);},'assistant-ask':()=>assistantAnswer($('#assistant-question').value),
 'studio-upload':()=>$('#studio-file').click(),'studio-remove':()=>{if(state.studio.loading)return;URL.revokeObjectURL(state.studio.url);state.studio.file=null;state.studio.url=null;state.studio.output=null;refreshView();},'generate':()=>generateContent(),'regenerate':()=>generateContent(true),
 'copy':async()=>{const o=state.studio.output;if(!o)return;const text=[o.caption,o.hashtags,o.cta].join('\n\n');try{await navigator.clipboard.writeText(text);toast('Content copied.');}catch{const area=document.createElement('textarea');area.value=text;area.style.position='fixed';area.style.opacity='0';document.body.append(area);area.select();const ok=document.execCommand('copy');area.remove();if(ok)toast('Content copied.');else openModal('Copy your content',`<textarea rows="12" readonly aria-label="Content to copy">${escapeHTML(text)}</textarea><p class="muted small-text">Select the text and press Ctrl+C or Command+C.</p>`);}},
 'task-new':()=>taskDialog(),'task-edit':()=>taskDialog(id),'task-delete':()=>confirmDelete('tasks',id,'task'),
 'event-new':()=>eventDialog(),'event-edit':()=>eventDialog(id),'event-delete':()=>confirmDelete('events',id,'scheduled post'),
 'month-prev':()=>{state.month.setMonth(state.month.getMonth()-1);refreshView();},'month-next':()=>{state.month.setMonth(state.month.getMonth()+1);refreshView();},'month-today':()=>{state.month=new Date(new Date().getFullYear(),new Date().getMonth(),1);refreshView();},
 'asset-upload':uploadDialog,'asset-save':()=>{selectedFiles.forEach(f=>{const existing=state.assets.find(a=>a.name===f.name&&a.size===f.size&&!fileURLs.has(a.id));const id=existing?.id||uid();if(!existing)state.assets.push({id,name:f.name,size:f.size,type:f.type,kind:f.type.startsWith('image')?'Images':f.type.startsWith('video')?'Videos':'Documents'});fileURLs.set(id,URL.createObjectURL(f));});persist('assets');closeModal();refreshView();toast('Assets added to your local collection.');},
 'asset-open':()=>{const url=fileURLs.get(id);if(!url){toast('Upload the same file again to restore its preview.');uploadDialog();return;}const a=state.assets.find(a=>a.id===id);const link=document.createElement('a');link.href=url;link.target='_blank';link.rel='noopener';if(a.kind==='Documents'&&!/pdf/i.test(a.type))link.download=a.name;link.click();},'asset-delete':()=>confirmDelete('assets',id,'asset'),
 'connect':()=>{if(state.connections[p]){state.connections[p]=false;persist('connections');refreshView();toast(p+' disconnected in demo.');}else openModal('Connect '+p,`<div class="notice">Simulated connection. No authorization or provider access is requested.</div><p>Add Jobgen.ai Marketing as a demo ${p} account in this browser.</p><div class="modal-foot">${button('Cancel','modal-close')}${button('Connect demo account','connect-confirm','primary',`data-provider="${p}"`)}</div>`);},'connect-confirm':()=>{state.connections[p]=true;persist('connections');closeModal();refreshView();toast(p+' connected in demo mode.');},
 'lead-new':()=>recordDialog('lead'),'lead-edit':()=>recordDialog('lead',id),'lead-delete':()=>confirmDelete('leads',id,'lead'),'campaign-new':()=>recordDialog('campaign'),'campaign-edit':()=>recordDialog('campaign',id),'campaign-delete':()=>confirmDelete('campaigns',id,'campaign'),'competitor-new':()=>recordDialog('competitor'),'competitor-delete':()=>confirmDelete('competitors',id,'competitor'),'rule-new':()=>recordDialog('rule'),'rule-delete':()=>confirmDelete('rules',id,'rule'),
 'rule-toggle':()=>{const r=state.rules.find(r=>r.id===id);r.enabled=!r.enabled;persist('rules');refreshView();},'rule-test':()=>{const r=state.rules.find(r=>r.id===id);if(!r.enabled)return;r.runs++;persist('rules');refreshView();openModal('Simulation complete',`<div class="notice">No external action was performed.</div><p><b>Trigger:</b> ${escapeHTML(r.trigger)}</p><p><b>Prepared action:</b> ${escapeHTML(r.action)}</p><div class="assistant-response">Hi there! Thanks for connecting with Jobgen.ai. We’re here to help you find your next opportunity. Let’s start a conversation.</div>`);},
 'login-toggle':()=>{state.loginMode=state.loginMode==='signin'?'register':'signin';shell();},'reset':()=>{pendingDelete={collection:'reset'};openModal('Reset your local workspace?',`<p class="muted">This clears all Jobgen vanilla demo records and preferences from this browser.</p><div class="modal-foot">${button('Cancel','modal-close')}${button('Reset data','confirm-delete','danger')}</div>`);},
 'confirm-delete':()=>{if(!pendingDelete)return;if(pendingDelete.collection==='reset'){for(const name of ['theme','tasks','events','assets','connections','preferences','leads','campaigns','competitors','rules','profile']){try{localStorage.removeItem(key(name));}catch{}}location.reload();return;}const {collection,id}=pendingDelete;if(collection==='assets'&&fileURLs.has(id)){URL.revokeObjectURL(fileURLs.get(id));fileURLs.delete(id);}state[collection]=state[collection].filter(x=>x.id!==id);persist(collection);pendingDelete=null;closeModal();refreshView();toast('Deleted from your local workspace.');}
 };handlers[action]?.();return;}
 const date=event.target.closest('[data-date]');if(date){eventDialog(null,date.dataset.date);return;}
 if(event.target.classList.contains('modal-backdrop'))closeModal();
});
document.addEventListener('submit',event=>{event.preventDefault();const form=event.target;if(!form.reportValidity())return;const data=Object.fromEntries(new FormData(form));const id=form.dataset.id;
 if(form.id==='task-form'){if(!data.title.trim()){toast('Add a task title.');return;}const task={...data,id:id||uid(),title:data.title.trim()};if(id)state.tasks=state.tasks.map(t=>t.id===id?task:t);else state.tasks.push(task);persist('tasks');closeModal();refreshView();toast('Task saved.');}
 if(form.id==='event-form'){if(!data.title.trim()){toast('Add a post title.');return;}const e={...data,id:id||uid(),title:data.title.trim()};if(id)state.events=state.events.map(x=>x.id===id?e:x);else state.events.push(e);persist('events');closeModal();refreshView();toast('Post scheduled locally.');}
 if(form.id==='record-form'){const kind=form.dataset.kind;const collection={lead:'leads',campaign:'campaigns',competitor:'competitors',rule:'rules'}[kind];if(!data.name.trim()){toast('Add a name.');return;}const previous=state[collection].find(r=>r.id===id);const record={...previous,...data,id:id||uid(),name:data.name.trim()};if(kind==='lead')record.value=Number(data.value);if(kind==='campaign'){record.budget=Number(data.budget);record.progress=previous?.progress||0;}if(kind==='rule'){record.enabled=true;record.runs=0;}if(id)state[collection]=state[collection].map(r=>r.id===id?record:r);else state[collection].push(record);persist(collection);closeModal();refreshView();toast('Saved locally.');}
 if(form.id==='login-form'){save('profile',{name:data.name||'Jobgen Marketing',email:data.email});navigate('dashboard');toast('Welcome to your demo workspace.');}
});
document.addEventListener('input',event=>{const t=event.target;
 if(t.id==='task-search'||t.id==='asset-search'){const name=t.id==='task-search'?'taskSearch':'assetSearch';const cursor=t.selectionStart;state[name]=t.value;refreshView();const input=$('#'+t.id);input.focus();if(cursor!==null)input.setSelectionRange(cursor,cursor);}
 if(t.id==='studio-notes')state.studio.notes=t.value;
 if(t.id.startsWith('output-')&&state.studio.output)state.studio.output[t.id.slice(7)]=t.value;
});
document.addEventListener('change',event=>{const t=event.target;
 if(t.id==='priority-filter'){state.taskPriority=t.value;refreshView();}
 if(t.dataset.taskStatus){state.tasks.find(x=>x.id===t.dataset.taskStatus).status=t.value;persist('tasks');refreshView();toast('Task moved.');}
 if(t.dataset.leadStage){state.leads.find(x=>x.id===t.dataset.leadStage).stage=t.value;persist('leads');refreshView();}
 if(t.dataset.campaignStatus){state.campaigns.find(x=>x.id===t.dataset.campaignStatus).status=t.value;persist('campaigns');refreshView();}
 if(t.id==='analytics-range'){state.analyticsRange=Number(t.value);refreshView();}
 if(t.id==='studio-platform')state.studio.platform=t.value;
 if(t.id==='studio-tone')state.studio.tone=t.value;
 if(t.id==='studio-file')studioFile(t.files[0]);
 if(t.id==='asset-files')chooseAssets(t.files);
 if(t.id==='theme-select'){state.theme=t.value;persist('theme');document.documentElement.dataset.theme=state.theme;refreshView();}
 if(t.id==='default-platform'||t.id==='default-tone'){state.preferences[t.id.slice(8)]=t.value;persist('preferences');toast('Preference saved.');}
});
document.addEventListener('keydown',event=>{const modal=$('.modal');if(modal){if(event.key==='Escape'){closeModal();return;}if(event.key==='Tab'){const focusable=$$('button:not(:disabled),input,select,textarea,a[href]',modal);const first=focusable[0],last=focusable.at(-1);if(event.shiftKey&&(document.activeElement===first||document.activeElement===modal)){event.preventDefault();last?.focus();}else if(!event.shiftKey&&(document.activeElement===last||document.activeElement===modal)){event.preventDefault();first?.focus();}}}else if((event.key==='Enter'||event.key===' ')&&event.target.matches('[data-date]')){event.preventDefault();eventDialog(null,event.target.dataset.date);}});
let draggingId=null;
document.addEventListener('dragstart',event=>{const task=event.target.closest('[data-task-id]');if(!task)return;draggingId=task.dataset.taskId;event.dataTransfer.setData('text/plain',draggingId);event.dataTransfer.effectAllowed='move';task.classList.add('dragging');});
document.addEventListener('dragend',()=>{draggingId=null;$$('.over,.dragging').forEach(el=>el.classList.remove('over','dragging'));});
document.addEventListener('dragover',event=>{const zone=event.target.closest('.column,#studio-drop,#asset-drop');if(!zone)return;event.preventDefault();zone.classList.add('over');if(event.dataTransfer)event.dataTransfer.dropEffect=zone.classList.contains('column')?'move':'copy';});
document.addEventListener('dragleave',event=>{const zone=event.target.closest('.column,#studio-drop,#asset-drop');if(zone&&!zone.contains(event.relatedTarget))zone.classList.remove('over');});
document.addEventListener('drop',event=>{const zone=event.target.closest('.column,#studio-drop,#asset-drop');if(!zone)return;event.preventDefault();zone.classList.remove('over');if(zone.id==='studio-drop'){studioFile(event.dataTransfer.files[0]);return;}if(zone.id==='asset-drop'){chooseAssets(event.dataTransfer.files);return;}const id=draggingId||event.dataTransfer.getData('text/plain');const task=state.tasks.find(t=>t.id===id);if(task){task.status=zone.dataset.status;persist('tasks');refreshView();toast('Task moved to '+statuses.find(s=>s[0]===task.status)[1]+'.');}draggingId=null;});
window.addEventListener('beforeunload',()=>{for(const url of fileURLs.values())URL.revokeObjectURL(url);if(state.studio.url)URL.revokeObjectURL(state.studio.url);});
shell();
